import java.util.Scanner;

public class Main {
    public static long getGCD(long a, long b) {
        while (b != 0) {
            long temp = a % b;
            a = b;
            b = temp;
        }
        return a;
    }

    static class Fraction {
        long num, den;

        Fraction() {
            this.num = 0;
            this.den = 1;
        }

        Fraction(long n, long d) {
            this.num = n;
            this.den = d;
        }

        void reduce() {
            long g = getGCD(num, den);
            num /= g;
            den /= g;
        }

        boolean lessThan(Fraction other) {
            return this.num * other.den < other.num * this.den;
        }

        void print() {
            System.out.print(num + "/" + den);
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long x = sc.nextLong();
        long y = sc.nextLong();
        long n = sc.nextLong();

        Fraction limit = new Fraction(50, 1);
        Fraction base = new Fraction(x, y);
        long best_r = 0, best_i = 1;

        for (long i = 1; i <= n; ++i) {
            long r = (base.num * i) / base.den;
            long z = (base.num * i) % base.den;
            if (z > base.den / 2) {
                r++;
                z = base.den - z;
            }
            Fraction current = new Fraction(z, i * base.den);
            if (current.lessThan(limit)) {
                limit = current;
                best_r = r;
                best_i = i;
            }
        }
        System.out.print(best_r);
        sc.close();
    }
}
